import{c as s,Q as n,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const p="/assets/Normal%E6%A8%A1%E5%BC%8F%E5%92%8CCounter%E6%A8%A1%E5%BC%8F%E4%B8%8B%E7%9A%84Scalar%E6%89%A7%E8%A1%8C%E6%97%B6%E9%97%B4%E5%AF%B9%E6%AF%94.C1QecCNt.png",l="/assets/Normal%E6%A8%A1%E5%BC%8F%E5%92%8CCounter%E6%A8%A1%E5%BC%8F%E4%B8%8B%E7%9A%84Vector%E6%89%A7%E8%A1%8C%E6%97%B6%E9%97%B4%E5%AF%B9%E6%AF%94.BCOVZVg1.png",C=JSON.parse('{"title":"Vector算子灵活运用Counter模式","description":"","frontmatter":{},"headers":[{"level":1,"title":"Vector算子灵活运用Counter模式","slug":"vector算子灵活运用counter模式"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/矢量计算/Vector算子灵活运用Counter模式.md","filePath":"guide/算子实践参考/SIMD算子性能优化/矢量计算/Vector算子灵活运用Counter模式.md"}'),c={name:"guide/算子实践参考/SIMD算子性能优化/矢量计算/Vector算子灵活运用Counter模式.md"};function r(o,a,i,m,d,u){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="vector算子灵活运用counter模式" tabindex="-1">Vector算子灵活运用Counter模式 <a class="header-anchor" href="#vector算子灵活运用counter模式" aria-label="Permalink to &quot;Vector算子灵活运用Counter模式&quot;">​</a></h1><p>【优先级】高</p><p>【描述】Normal模式下，通过迭代次数repeatTimes和掩码mask，控制Vector算子中矢量计算API的计算数据量；当用户想要指定API计算的总元素个数时，首先需要自行判断是否存在不同的主块和尾块，主块需要将mask设置为全部元素参与计算，并且计算主块所需迭代次数，然后根据尾块中剩余元素个数重置mask，再进行尾块的运算，在此过程中涉及大量Scalar计算。</p><p>Counter模式下，用户不需要计算迭代次数以及判断是否存在尾块，将mask模式设置为Counter模式后，只需要设置mask为{0, 总元素个数}，然后调用相应的API，处理逻辑更简便，减少了指令数量和Scalar计算量，同时更加高效地利用了指令单次执行的并发能力，进而提升性能。</p><p>提示：Normal模式和Counter模式、掩码的介绍可参考<a href="./../../../编程指南/类库API/基础API/常用操作速查指导/如何使用掩码操作API.html">如何使用掩码操作API</a>。</p><p>以下反例和正例中的代码均以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/00_compilation/custom_op" target="_blank" rel="noreferrer">AddCustom</a>算子为例，修改其中Add接口的调用代码，以说明Counter模式的优势。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Add(zLocal, xLocal, yLocal, this-&gt;tileLength);</span></span></code></pre></div><p>【反例】</p><p>输入数据类型为half的xLocal, yLocal，数据量均为15000。Normal模式下，每个迭代内参与计算的元素个数最多为256B/sizeof(half)=128个，所以15000次Add计算会被分为：主块计算15000/128=117次迭代，每次迭代128个元素参与计算；尾块计算1次迭代，该迭代15000-117*128=24个元素参与计算。从代码角度，需要计算主块的repeatTimes、尾块元素个数；主块计算时，设置mask值为128，尾块计算时，需要设置mask值为尾块元素个数24；这些过程均涉及Scalar计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t ELE_SIZE = 15000;</span></span>
<span class="line"><span>AscendC::BinaryRepeatParams binaryParams;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uint32_t numPerRepeat = 256 / sizeof(DTYPE_X);  // DTYPE_X为half数据类型</span></span>
<span class="line"><span>uint32_t mainRepeatTimes = ELE_SIZE / numPerRepeat;</span></span>
<span class="line"><span>uint32_t tailEleNum = ELE_SIZE % numPerRepeat;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;DTYPE_X, AscendC::MaskMode::NORMAL&gt;(numPerRepeat); // 设置normal模式mask，使每个迭代计算128个数</span></span>
<span class="line"><span>AscendC::Add&lt;DTYPE_X, false&gt;(zLocal, xLocal, yLocal, AscendC::MASK_PLACEHOLDER, mainRepeatTimes, binaryParams);   // MASK_PLACEHOLDER值为0，此处为mask占位，实际mask值以SetVectorMask设置的为准</span></span>
<span class="line"><span>if (tailEleNum &gt; 0) {</span></span>
<span class="line"><span>     AscendC::SetVectorMask&lt;DTYPE_X, AscendC::MaskMode::NORMAL&gt;(tailEleNum); // 设置normal模式mask，使每个迭代计算24个数</span></span>
<span class="line"><span>     // 偏移tensor的起始地址，在xLocal和yLocal的14976个元素处，进行尾块计算</span></span>
<span class="line"><span>     AscendC::Add&lt;DTYPE_X, false&gt;(zLocal[mainRepeatTimes * numPerRepeat], xLocal[mainRepeatTimes * numPerRepeat], </span></span>
<span class="line"><span>           yLocal[mainRepeatTimes * numPerRepeat], AscendC::MASK_PLACEHOLDER, 1, binaryParams);  </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>AscendC::ResetMask();  // 还原mask值</span></span></code></pre></div><p>【正例】</p><p>输入数据类型为half的xLocal, yLocal，数据量均为15000。Counter模式下，只需要设置mask为所有参与计算的元素个数15000，然后直接调用Add指令，即可完成所有计算，不需要繁琐的主尾块计算，代码较为简练。</p><p>当要处理多达15000个元素的矢量计算时，Counter模式的优势更明显，不需要反复修改主块和尾块不同的mask值，减少了指令条数以及Scalar计算量，并充分利用了指令单次执行的并发能力。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t ELE_SIZE = 15000;</span></span>
<span class="line"><span>AscendC::BinaryRepeatParams binaryParams;</span></span>
<span class="line"><span>AscendC::SetMaskCount();</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;DTYPE_X, AscendC::MaskMode::COUNTER&gt;(ELE_SIZE);  // 设置counter模式mask，总共计算15000个数</span></span>
<span class="line"><span>AscendC::Add&lt;DTYPE_X, false&gt;(zLocal, xLocal, yLocal, AscendC::MASK_PLACEHOLDER, 1, binaryParams);                // MASK_PLACEHOLDER值为0，此处为mask占位，实际mask值以SetVectorMask设置的为准</span></span>
<span class="line"><span>AscendC::ResetMask();  // 还原mask值</span></span></code></pre></div><p>【性能对比】</p><p><strong>图 1</strong> Normal模式和Counter模式下的Scalar执行时间对比<br><img src="`+p+'" alt="" title="Normal模式和Counter模式下的Scalar执行时间对比"></p><p><strong>图 2</strong> Normal模式和Counter模式下的Vector执行时间对比<br><img src="'+l+'" alt="" title="Normal模式和Counter模式下的Vector执行时间对比"></p><p>以上性能数据是分别循环运行1000次反例和正例代码得到的Scalar和Vector执行时间。从上述两幅性能对比图和示例代码可以看到，使用Counter模式能够大幅度简化代码，易于维护，同时能够降低Scalar和Vector计算耗时，获得性能提升。</p>',18)])])}const E=s(c,[["render",r]]);export{C as __pageData,E as default};
